import { useState } from "react";
import { Container, Row, Col } from "react-bootstrap";
import contactImg from "../assets/img/contact-img.svg";
import emailjs from "emailjs-com";

const Contact = () => {
    const formInitialDetails = {
        firstName: '',
        lastName: '',
        email: '',
        phone: '',
        message: ''
    };
    const [formDetails, setFormDetails] = useState(formInitialDetails);
    const [buttonText, setButtonText] = useState('Send');
    const [status, setStatus] = useState({});

    const onFormUpdate = (category, value) => {
        setFormDetails({ ...formDetails, [category]: value });
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setButtonText("Sending...");

        const { firstName, lastName, email, phone, message } = formDetails;
        
        const templateParams = {
            firstName: formDetails.firstName,
            lastName: formDetails.lastName,
            email: formDetails.email,
            phone: formDetails.phone,
            message: formDetails.message,
        };

        if (!firstName || !lastName || !email || !phone || !message) {
            setStatus({ success: false, message: 'Please fill in all fields.' });
            return;
        }

        const phoneRegex = /^\+?\d{10,15}$/; // Allows + and 10–15 digits
        if (!phoneRegex.test(phone)) {
            setStatus({ success: false, message: 'Please enter a valid phone number (10–15 digits).' });
            setButtonText("Send");
            return;
        }

        try {
            await emailjs.send(
                'service_utchrqq',
                'template_2s41g5r',
                templateParams,
                'h1f1-LmEBA2Vb7rQh'
            );
            setButtonText("Send");
            setFormDetails(formInitialDetails);
            setStatus({ success: true, message: 'Message sent successfully!' });
        } catch (error) {
            console.error('EmailJS Error:', error);
            setStatus({ success: false, message: 'Failed to send message. Try again.' });
        }
    };

    return (
        <section className="contact" id="connect">
            <Container>
                <Row className="align-items-center">
                    <Col size={12} md={6}>
                        <img src={contactImg} alt="Contact Us" />
                    </Col>
                    <Col size={12} md={6}>
                        <div className="animate__animated animate__fadeIn">
                            <h2>Get In Touch</h2>
                            <form onSubmit={handleSubmit}>
                                <Row>
                                    <Col sm={6} className="px-1">
                                        <input type="text" value={formDetails.firstName} placeholder="First Name"
                                            onChange={(e) => onFormUpdate('firstName', e.target.value)} required />
                                    </Col>
                                    <Col sm={6} className="px-1">
                                        <input type="text" value={formDetails.lastName} placeholder="Last Name"
                                            onChange={(e) => onFormUpdate('lastName', e.target.value)} required />
                                    </Col>
                                    <Col sm={6} className="px-1">
                                        <input type="email" value={formDetails.email} placeholder="Email Address"
                                            onChange={(e) => onFormUpdate('email', e.target.value)} required />
                                    </Col>
                                    <Col sm={6} className="px-1">
                                        <input type="tel" value={formDetails.phone} placeholder="Phone No."
                                            onChange={(e) => onFormUpdate('phone', e.target.value)} required />
                                    </Col>
                                    <Col size={12} className="px-1">
                                        <textarea rows="6" value={formDetails.message} placeholder="Message"
                                            onChange={(e) => onFormUpdate('message', e.target.value)} required></textarea>
                                        <button type="submit"><span>{buttonText}</span></button>
                                    </Col>
                                    {
                                        status.message &&
                                        <Col>
                                            <p className={status.success === false ? "danger" : "success"}>
                                                {status.message}
                                            </p>
                                        </Col>
                                    }
                                </Row>
                            </form>
                        </div>
                    </Col>
                </Row>
            </Container>
        </section>
    );
};

export default Contact;
